import{_ as t,o as r,c as o,a0 as n}from"./chunks/framework.DNNiP2TX.js";const l=JSON.parse('{"title":"@shutter-network/concorde/users routes","description":"","frontmatter":{"title":"@shutter-network/concorde/users routes"},"headers":[],"relativePath":"reference/routes/users.md","filePath":"reference/routes/users.md"}'),s={name:"reference/routes/users.md"};function a(i,e,d,c,h,g){return r(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="shutter-network-concorde-users" tabindex="-1">@shutter-network/concorde/users <a class="header-anchor" href="#shutter-network-concorde-users" aria-label="Permalink to &quot;@shutter-network/concorde/users&quot;">​</a></h1><p>The HTTP routes this component serves: 2 on the Agent server and 1 on the Public server.</p><p><strong>Every path is relative.</strong> Each one is printed as the plugin declares it, under whatever prefix the component&#39;s constructor registers that plugin at. This page states no mount point, because the constructor is where the mount point is decided.</p><p>Generated from what the route plugins in <code>src/users/routes.ts</code> declare, which is what a running Gateway serves at <code>GET /openapi.json</code>. Never edited by hand.</p><h2 id="agent-server" tabindex="-1">Agent server <a class="header-anchor" href="#agent-server" aria-label="Permalink to &quot;Agent server&quot;">​</a></h2><p><strong>The Agent server has no authentication of any kind.</strong> Everything below is reachable by the agent, and therefore by an injected prompt (<a href="https://github.com/shutter-network/concorde/blob/main/docs/adr/0003-prompt-injection-is-an-accepted-risk.md" target="_blank" rel="noreferrer">ADR-0003</a>). Nothing on it names a credential.</p><h3 id="get" tabindex="-1"><code>GET /</code> <a class="header-anchor" href="#get" aria-label="Permalink to &quot;`GET /`&quot;">​</a></h3><p><strong>Read Users, newest first</strong></p><p>Every User this Gateway has admitted, newest first. <strong>These routes are reads.</strong> There is no create here: an agent that could mint a User and give it a credential has minted itself an account, so admitting a User is the Operator&#39;s own code and has no route. Users cannot be searched or filtered. Attributes are arbitrary JSON that the Gateway cannot index, and a User has no natural key to match on. <code>limit</code> defaults to 50 and is capped at 200. A larger value is <strong>refused with a 400</strong> rather than quietly reduced. There is no cursor and no offset, and nothing to narrow by. The Users past the cap are not reachable through this route. An unknown query parameter is a <strong>400</strong>, not a filter that did nothing and a request answered with everything.</p><p>Tagged <code>Users</code>.</p><p><strong>Query parameters</strong></p><ul><li><strong><code>limit</code></strong> <code>integer</code>, optional, 1 to 200, default <code>50</code></li></ul><p><strong>Responses</strong></p><p><strong><code>200</code></strong> <code>application/json</code></p><p>The most recently created Users.</p><ul><li><strong><code>users</code></strong> array of <code>object</code>, required <ul><li><p><strong><code>id</code></strong> <code>string</code>, required</p></li><li><p><strong><code>attributes</code></strong> any JSON, required</p><p>Arbitrary JSON, defined by the deployment and interpreted by nothing in the Gateway. This is where grouping and therefore authorization live. Nothing on any HTTP surface writes them: a User is admitted from the Operator&#39;s own code, and <code>setAttributes</code> has no route anywhere.</p></li><li><p><strong><code>createdAt</code></strong> <code>string</code>, required</p></li></ul></li></ul><p><strong><code>400</code></strong> <code>application/json</code></p><p>The <code>limit</code> is out of range or not an integer, or a parameter this route does not take was written.</p><ul><li><strong><code>statusCode</code></strong> <code>integer</code>, required</li><li><strong><code>error</code></strong> <code>string</code>, required</li><li><strong><code>message</code></strong> <code>string</code>, required</li></ul><h3 id="get-id" tabindex="-1"><code>GET /{id}</code> <a class="header-anchor" href="#get-id" aria-label="Permalink to &quot;`GET /{id}`&quot;">​</a></h3><p><strong>Read one User by id</strong></p><p>One User, by the opaque id whoever admitted them was told. There is no email and no username to find one by. Users cannot be searched or filtered. Attributes are arbitrary JSON that the Gateway cannot index, and a User has no natural key to match on. An unknown query parameter is a <strong>400</strong>, not a filter that did nothing and a request answered with everything.</p><p>Tagged <code>Users</code>.</p><p><strong>Path parameters</strong></p><ul><li><strong><code>id</code></strong> <code>string</code>, required, matching <code>^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$</code></li></ul><p><strong>Responses</strong></p><p><strong><code>200</code></strong> <code>application/json</code></p><p>The User.</p><ul><li><p><strong><code>id</code></strong> <code>string</code>, required</p></li><li><p><strong><code>attributes</code></strong> any JSON, required</p><p>Arbitrary JSON, defined by the deployment and interpreted by nothing in the Gateway. This is where grouping and therefore authorization live. Nothing on any HTTP surface writes them: a User is admitted from the Operator&#39;s own code, and <code>setAttributes</code> has no route anywhere.</p></li><li><p><strong><code>createdAt</code></strong> <code>string</code>, required</p></li></ul><p><strong><code>400</code></strong> <code>application/json</code></p><p>The id in the path is not a uuid, or a query parameter was written.</p><ul><li><strong><code>statusCode</code></strong> <code>integer</code>, required</li><li><strong><code>error</code></strong> <code>string</code>, required</li><li><strong><code>message</code></strong> <code>string</code>, required</li></ul><p><strong><code>404</code></strong> <code>application/json</code></p><p>No User has that id.</p><ul><li><strong><code>statusCode</code></strong> <code>integer</code>, required</li><li><strong><code>error</code></strong> <code>string</code>, required</li><li><strong><code>message</code></strong> <code>string</code>, required</li></ul><h2 id="public-server" tabindex="-1">Public server <a class="header-anchor" href="#public-server" aria-label="Permalink to &quot;Public server&quot;">​</a></h2><p><strong>The Public server is what a User&#39;s client calls.</strong> Which credential each route wants, and which wants none, is in that route&#39;s own description below.</p><h3 id="get-me" tabindex="-1"><code>GET /me</code> <a class="header-anchor" href="#get-me" aria-label="Permalink to &quot;`GET /me`&quot;">​</a></h3><p><strong>Read the authenticated User</strong></p><p>The User this request is acting as, in the same shape the agent&#39;s reads answer with. A client resuming after a restart recovers exactly what it was told. The Attributes governing this User&#39;s authorization are included. They are not hidden from the User they are about.</p><p>It echoes the authenticated User and reads nothing else, so it answers the same way whichever scheme this deployment authenticated the request with. <strong>Requires authentication.</strong> Present a credential of any scheme this deployment accepts, which is <code>Authorization: Bearer &lt;token&gt;</code> wherever the password login is registered. The User answered with is the one the Gateway authenticated, and no parameter anywhere names another. This route takes no query parameters at all. A credential travels in the body or in the Authorization header, never in a URL. An unknown query parameter is a <strong>400</strong>, not a filter that did nothing and a request answered with everything.</p><p>Tagged <code>Users</code>.</p><p><strong>Responses</strong></p><p><strong><code>200</code></strong> <code>application/json</code></p><p>The User the Gateway authenticated.</p><ul><li><p><strong><code>id</code></strong> <code>string</code>, required</p></li><li><p><strong><code>attributes</code></strong> any JSON, required</p><p>Arbitrary JSON, defined by the deployment and interpreted by nothing in the Gateway. This is where grouping and therefore authorization live. Nothing on any HTTP surface writes them: a User is admitted from the Operator&#39;s own code, and <code>setAttributes</code> has no route anywhere.</p></li><li><p><strong><code>createdAt</code></strong> <code>string</code>, required</p></li></ul><p><strong><code>400</code></strong> <code>application/json</code></p><p>A query parameter was written, and this route takes none.</p><ul><li><strong><code>statusCode</code></strong> <code>integer</code>, required</li><li><strong><code>error</code></strong> <code>string</code>, required</li><li><strong><code>message</code></strong> <code>string</code>, required</li></ul><p><strong><code>401</code></strong> <code>application/json</code></p><p>Authentication failed, which is the whole of what is said: a wrong password, an id nobody holds, a User with no password, and a Token that is missing, malformed, unknown or expired are one status and one message, so nothing here answers who exists.</p><ul><li><strong><code>statusCode</code></strong> <code>integer</code>, required</li><li><strong><code>error</code></strong> <code>string</code>, required</li><li><strong><code>message</code></strong> <code>string</code>, required</li></ul>',52)])])}const p=t(s,[["render",a]]);export{l as __pageData,p as default};
